class Solution {
    public int longestBalanced(String s) {
        int n = s.length(), best = 0;
        for (int i = 0; i < n; i++) {
            int depth = 0;
            for (int j = i; j < n; j++) {
                depth += s.charAt(j) == '(' ? 1 : -1;
                if (depth < 0) break;
                if (depth == 0) best = Math.max(best, j - i + 1);
            }
        }
        return best;
    }
}

