class Solution {
    public int longestBalanced(String s) {
        int n = s.length(), best = 0, opened = 0, closed = 0;
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == '(') opened++; else closed++;
            if (opened == closed) best = Math.max(best, 2 * closed);
            else if (closed > opened) opened = closed = 0;
        }
        opened = closed = 0;
        for (int i = n - 1; i >= 0; i--) {
            if (s.charAt(i) == '(') opened++; else closed++;
            if (opened == closed) best = Math.max(best, 2 * opened);
            else if (opened > closed) opened = closed = 0;
        }
        return best;
    }
}

